f1_lowered_asl:
class.students = 8
class.construction_paper_each = 3
class.glue_bottles = 6
class.construction_paper_total = (class.students * class.construction_paper_each)
class.supplies_initial = (class.construction_paper_total + class.glue_bottles)
class.supplies_dropped = (class.supplies_initial / 2)
class.supplies_after_drop = (class.supplies_initial - class.supplies_dropped)
class.supplies_final = (class.supplies_after_drop + 5)
RETURN class.supplies_final

f2_lowered_asl:
class.students = 8
class.construction_paper_each = 3
class.glue_bottles = 6
class.construction_paper_total = (class.students * class.construction_paper_each)
class.supplies_initial = (class.construction_paper_total + class.glue_bottles)
class.supplies_dropped = (class.supplies_initial * 1 / 2)
class.supplies_after_drop = (class.supplies_initial - (class.supplies_dropped))
class.supplies_final = (class.supplies_after_drop + 5)
RETURN class.supplies_final

f1_lowered_asl:
class.students_total = 200
class.blue_likers = percent_of(class.students_total, 30)
class.non_blue_likers = (class.students_total - class.blue_likers)
class.red_likers = percent_of(class.non_blue_likers, 40)
class.yellow_likers = (class.non_blue_likers - class.red_likers)
class.yellow_and_blue_likers = (class.yellow_likers + class.blue_likers)
RETURN class.yellow_and_blue_likers

f2_lowered_asl:
class.students_total = 200
class.blue_likers = percent_of(class.students_total, 30)
class.non_blue_likers = (class.students_total - (class.blue_likers))
class.red_likers = percent_of(class.non_blue_likers, 40)
class.yellow_likers = (class.non_blue_likers - (class.red_likers))
class.yellow_and_blue_likers = (class.yellow_likers + class.blue_likers)
RETURN class.yellow_and_blue_likers

