school.total_students = 80
class.a.students = percent_of(school.total_students, 40)
class.b.students = (class.a.students - 21)
class.c.students = (school.total_students - class.a.students - class.b.students)
RETURN class.c.students

f2_lowered_asl:
school.total_students = 80
class.a.students = percent_of(school.total_students, 40)
class.b.students = (class.a.students - 21)
class.c.students = (school.total_students - (class.a.students + class.b.students))
RETURN class.c.students
